// Render skills and interests from data.json (generated by backend/build_data.py)
const el = (tag, text, cls) => Object.assign(document.createElement(tag), { textContent: text, className: cls || "" });

fetch("assets/data.json")
  .then(r => r.json())
  .then(({ skills, interests }) => {
    const box = document.getElementById("skills-list");
    box.innerHTML = "";
    for (const [group, items] of Object.entries(skills)) {
      const g = el("div", "", "group");
      g.append(el("h3", group));
      const ul = el("ul", "", "chips");
      items.forEach(s => ul.append(el("li", s)));
      g.append(ul);
      box.append(g);
    }
    const il = document.getElementById("interest-list");
    interests.forEach(i => il.append(el("li", i)));
  })
  .catch(() => { document.getElementById("skills-list").textContent = "Run backend/build_data.py to generate assets/data.json."; });

// Hero: a small neural network with a signal passing through it
const cv = document.getElementById("net"), cx = cv.getContext("2d");
const layers = [4, 6, 6, 3];
let nodes = [], t = 0;
function layout() {
  cv.width = cv.offsetWidth; cv.height = cv.offsetHeight;
  const w = cv.width, h = cv.height, x0 = w * (w > 700 ? .5 : .1), span = w - x0 - 20;
  nodes = layers.map((n, l) => Array.from({ length: n }, (_, i) =>
    ({ x: x0 + span * l / (layers.length - 1), y: h * .2 + h * .6 * (i + .5) / n })));
}
function draw() {
  cx.clearRect(0, 0, cv.width, cv.height);
  const active = Math.floor(t / 40) % layers.length;
  nodes.forEach((L, l) => L.forEach(a => {
    if (nodes[l + 1]) nodes[l + 1].forEach(b => {
      cx.strokeStyle = l === active ? "rgba(242,182,50,.55)" : "rgba(120,170,230,.25)";
      cx.beginPath(); cx.moveTo(a.x, a.y); cx.lineTo(b.x, b.y); cx.stroke();
    });
  }));
  nodes.forEach((L, l) => L.forEach(a => {
    cx.fillStyle = l === active ? "#f2b632" : "#9fb4cf";
    cx.beginPath(); cx.arc(a.x, a.y, 6, 0, 7); cx.fill();
  }));
  t++;
}
layout(); draw();
addEventListener("resize", () => { layout(); draw(); });
if (!matchMedia("(prefers-reduced-motion: reduce)").matches) setInterval(draw, 40);
